function Pill({ children, tone = 'blue' }) {
  const color = tone === 'mint' ? COLORS.mint : tone === 'amber' ? COLORS.amber : tone === 'coral' ? COLORS.coral : COLORS.blue;
  return <View style={[styles.pill, { backgroundColor: `${color}22` }]}><Text style={[styles.pillText, { color }]}>{children}</Text></View>;
}

function Card({ children, style }) { return <View style={[styles.card, style]}>{children}</View>; }
function AnimatedCard({ children, style, animationKey, duration = 180 }) { const [reduceMotion, setReduceMotion] = useState(false); const opacity = useRef(new Animated.Value(1)).current; const scale = useRef(new Animated.Value(1)).current; useEffect(() => { let mounted = true; AccessibilityInfo.isReduceMotionEnabled().then((enabled) => { if (mounted) setReduceMotion(Boolean(enabled)); }).catch(() => {}); const subscription = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion); return () => { mounted = false; subscription?.remove?.(); }; }, []); useEffect(() => { opacity.stopAnimation(); scale.stopAnimation(); if (reduceMotion) { opacity.setValue(1); scale.setValue(1); return; } Animated.parallel([Animated.timing(opacity, { toValue: 0.72, duration: Math.max(40, Math.round(duration * 0.45)), useNativeDriver: true }), Animated.timing(scale, { toValue: 0.985, duration: Math.max(40, Math.round(duration * 0.45)), useNativeDriver: true })]).start(() => { Animated.parallel([Animated.timing(opacity, { toValue: 1, duration, easing: Easing.out(Easing.cubic), useNativeDriver: true }), Animated.timing(scale, { toValue: 1, duration, easing: Easing.out(Easing.cubic), useNativeDriver: true })]).start(); }); }, [animationKey, reduceMotion]); return <Animated.View style={{ opacity, transform: [{ scale }] }}><Card style={style}>{children}</Card></Animated.View>; }
