const getToolNoteSource = (entry) => typeof entry === 'object' && entry?.source ? entry.source : 'User-entered observation';



function AnimatedUndoBar({ message, actionLabel, onPress, accessibilityLabel, intensity = 'standard' }) { const [reduceMotion, setReduceMotion] = useState(false); const opacity = useRef(new Animated.Value(0)).current; const translateY = useRef(new Animated.Value(14)).current; useEffect(() => { let mounted = true; AccessibilityInfo.isReduceMotionEnabled().then((enabled) => { if (mounted) setReduceMotion(Boolean(enabled)); }).catch(() => {}); const subscription = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion); return () => { mounted = false; subscription?.remove?.(); }; }, []); useEffect(() => { opacity.stopAnimation(); translateY.stopAnimation(); if (reduceMotion) { opacity.setValue(1); translateY.setValue(0); return; } opacity.setValue(0); translateY.setValue(14); Animated.parallel([Animated.timing(opacity, { toValue: 1, duration: getMotionDuration(220, intensity, reduceMotion), easing: Easing.out(Easing.cubic), useNativeDriver: true }), Animated.timing(translateY, { toValue: 0, duration: getMotionDuration(220, intensity, reduceMotion), easing: Easing.out(Easing.cubic), useNativeDriver: true })]).start(); }, [message, reduceMotion, intensity]); return <Animated.View accessibilityLiveRegion="polite" style={[styles.undoBar, { opacity, transform: [{ translateY }] }]}><Text style={styles.undoText}>{message}</Text><TouchableOpacity accessibilityRole="button" accessibilityLabel={accessibilityLabel} onPress={onPress}><Text style={styles.undoAction}>{actionLabel}</Text></TouchableOpacity></Animated.View>; }

function MotionButton({ children, style, onPress, disabled = false, accessibilityLabel, accessibilityHint }) {
  const [reduceMotion, setReduceMotion] = useState(false);
  const scale = useRef(new Animated.Value(1)).current;
  useEffect(() => { let mounted = true; AccessibilityInfo.isReduceMotionEnabled().then((enabled) => { if (mounted) setReduceMotion(Boolean(enabled)); }).catch(() => {}); const subscription = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion); return () => { mounted = false; subscription?.remove?.(); }; }, []);
  const animate = (toValue) => { if (reduceMotion) return; Animated.timing(scale, { toValue, duration: 90, easing: Easing.out(Easing.quad), useNativeDriver: true }).start(); };
  return <Animated.View style={{ transform: [{ scale }] }}><TouchableOpacity accessibilityRole="button" accessibilityLabel={accessibilityLabel} accessibilityHint={accessibilityHint} accessibilityState={{ disabled }} disabled={disabled} style={style} onPress={onPress} onPressIn={() => animate(0.97)} onPressOut={() => animate(1)}>{children}</TouchableOpacity></Animated.View>;
}

function ActionButton({ label, onPress, accessibilityLabel, accessibilityHint, variant = 'primary', disabled = false, style }) { return <MotionButton accessibilityLabel={accessibilityLabel || label} accessibilityHint={accessibilityHint} disabled={disabled} style={[variant === 'secondary' ? styles.secondaryButton : styles.primaryButton, disabled && styles.reportActionDisabled, style]} onPress={onPress}><Text style={variant === 'secondary' ? styles.secondaryButtonText : styles.primaryButtonText}>{label}</Text>{variant === 'primary' ? <Text style={styles.buttonArrow}>→</Text> : null}</MotionButton>; }

function MotionIntensityControl({ value, onChange }) { return <View style={{ marginTop: 18 }}><Text style={styles.cardTitle}>Motion intensity</Text><Text style={styles.muted}>Choose how energetic Carwise animations feel. System reduced motion always takes priority.</Text><View style={[styles.segmentRow, { marginTop: 10 }]}>{[['gentle', 'Gentle'], ['standard', 'Standard'], ['lively', 'Lively']].map(([option, label]) => <TouchableOpacity key={option} accessibilityRole="radio" accessibilityLabel={`${label} motion intensity`} accessibilityState={{ selected: value === option }} style={[styles.segment, value === option && styles.segmentActive]} onPress={() => onChange(option)}><Text style={{ color: value === option ? '#fff' : COLORS.muted, fontWeight: '800', fontSize: 11 }}>{label}</Text></TouchableOpacity>)}</View></View>; }

function RecoverySummary({ entries, onOpen }) { const recentEntries = getRecentRecoveryEntries(entries); return <Card><Text style={styles.cardEyebrow}>RECOVERY LOG</Text>{recentEntries.length ? recentEntries.map((entry) => <View key={entry.at} style={styles.detailLine}><Text style={styles.cardTitle}>{entry.operation} · {entry.outcome === 'success' ? 'Complete' : 'Needs attention'}</Text><Text style={styles.muted}>{entry.detail}</Text><Text style={styles.muted}>{getSafeDateLabel(entry.at, 'Time unavailable')}</Text></View>) : <Text style={styles.muted}>No local recovery events recorded this session.</Text>}<TouchableOpacity accessibilityRole="button" accessibilityLabel="Open detailed recovery log" style={styles.secondaryButton} onPress={onOpen}><Text style={styles.secondaryButtonText}>Open detailed recovery log</Text></TouchableOpacity></Card>; }



